<?php foreach($catalog[$kind][2]as $field=>$spec):$optional=str_starts_with($spec,'?');$type=ltrim($spec,'?');$value=$values[$field]??($type==='date'&&!$optional?ui_date('Y-m-d'):($field==='revisit_on'?ui_date('Y-m-d',strtotime('+30 days')):($type==='money0'?'0':''))); ?><label><?= e(t(ucfirst(str_replace('_',' ',$field)))) ?><?= $optional?' (optional)':'' ?>
