<?php else:$htmlType=match(true){$type==='date'||$type==='month'=>$type,str_starts_with($type,'int:')||in_array($type,['money','money0','decimal'],true)=>'number',default=>'text'};$attrs='';if(str_starts_with($type,'int:')){[,$min,$max]=explode(':',$type);$attrs='min="'.$min.'" max="'.$max.'" step="1"';}elseif(in_array($type,['money','money0','decimal'],true))$attrs='min="'.($type==='money'?'0.01':'0').'" step="'.($type==='decimal'?'0.0001':'0.01').'"'; ?><input type="<?= e($htmlType) ?>" name="<?= e($field) ?>" value="<?= e($value) ?>" maxlength="2000" <?= $optional?'':'required' ?> <?= $attrs ?>><?php endif; ?></label><?php endforeach; ?><div class="full"><button><?= e(t('Save')) ?></button> <a href="/life?page=<?= e($kind) ?>"><?= e(t('Cancel edit')) ?></a></div></form></section>
<section class="card"><h2><?= e(t('Saved')) ?> <?= e($catalog[$kind][1]) ?></h2><?php if(!$rows): ?><p><?= e(t('No records yet.')) ?></p><?php endif; ?><?php foreach($rows as $record): ?><article class="lesson-entry"><h3><?= e($record['title']??$record['name']??$record['item']??$record['provider']??$catalog[$kind][1]) ?></h3><dl><?php foreach($catalog[$kind][2]as $field=>$spec):$v=$record[$field];if($v!==null&&str_starts_with(ltrim($spec,'?'),'ref:')){$r=LifePlanningService::get(substr(ltrim($spec,'?'),4),(int)$v);$v=$r['title']??$r['name']??$r['item']??$r['provider']??$r['code']??$v;} ?><dt><?= e(t(ucfirst(str_replace('_',' ',$field)))) ?></dt><dd><?= nl2br(e($v)) ?></dd><?php endforeach; ?></dl><?php require __DIR__.'/record-detail.php'; ?><div class="inline"><a href="/life?page=<?= e($kind) ?>&amp;edit=<?= e($record['id']) ?>"><?= e(t('Edit')) ?></a><form method="post" action="/life/manage/<?= e($kind) ?>/<?= e($record['id']) ?>/archive"><?= csrf_field() ?><button class="quiet"><?= e(t('Archive')) ?></button></form></div></article><?php endforeach; ?></section>
